Translate("esES", "shadowfang-keep", {
	title = "Castillo de Colmillo Oscuro",
	aliases = { "Colmillo Oscuro" },
	sections = {
		{
			title = "Resumen",
			text = [=[El Castillo de Colmillo Oscuro se alza sobre una colina oscura en el sur del {link:silverpine-forest}Bosque de Argénteos{/link}, por encima de la {link:pyrewood-village}Aldea Piroleña{/link}. Antaño fue la sede del noble barón {link:baron-silverlaine}Silverlaine{/link}. Hoy es la guarida del archimago {link:archmage-arugal}Arugal{/link} y de los ferocanis a los que llama sus hijos. Hombres lobo merodean por sus salones, los huargos aúllan en sus patios, y los muertos de la casa del barón aún recorren las estancias donde fueron asesinados.]=],
		},
		{
			title = "Orígenes",
			text = [=[En la {link:third-war}Tercera Guerra{/link}, los magos del {link:kirin-tor}Kirin Tor{/link} lucharon contra la {link:scourge}Plaga{/link} en el norte. Cada mago que caía pronto se alzaba de nuevo para luchar por el enemigo, y la Plaga no hacía más que crecer. {link:archmage-arugal}Arugal{/link} no quiso aceptarlo. Contra el consejo de sus iguales, invocó a seres de más allá del mundo para llenar las filas menguantes de {link:city-of-dalaran}Dalaran{/link}. Lo que respondió a su llamada fueron los {red:worgen}ferocanis{/red}. Los voraces hombres lobo despedazaron a los no-muertos y después se volvieron contra los propios magos. Asediaron el castillo del barón {link:baron-silverlaine}Silverlaine{/link}, y este cayó en la sombra y la ruina. Enloquecido por la culpa, Arugal tomó a los ferocanis como sus propios hijos. Se retiró al castillo caído y le dio un nuevo nombre: Colmillo Oscuro.]=],
		},
		{
			title = "El presente",
			text = [=[Los {link:forsaken}Renegados{/link} no pueden dominar {link:silverpine-forest}Argénteos{/link} mientras {link:archmage-arugal}Arugal{/link} viva, y han jurado verlo muerto. El alto ejecutor {link:high-executor-hadrec}Hadrec{/link} envió a dos mortacechadores al castillo para descubrir sus secretos. No regresaron. El {link:kirin-tor}Kirin Tor{/link} también ha enviado a su propio agente, y no le fue mejor. Ambos esperan ahora en celdas cerca de la puerta. El guardián {link:keeper-bel-dugur}Bel'dugur{/link} de {link:undercity}Entrañas{/link} quiere un libro que se encuentra en algún lugar del castillo, la obra de un mago de {link:city-of-dalaran}Dalaran{/link} llamado Ur, que estudió otros mundos. En {link:the-sepulcher}El Sepulcro{/link}, un archimago muerto afirma ahora que Arugal nunca creó a los ferocanis.]=],
		},
		{
			title = "Dentro del castillo",
			text = [=[• {b}Las celdas.{/b} Cerca de la entrada, el ferocanis {link:rethilgore}Rethilgore{/link} mantiene encerrados a sus prisioneros.
• {b}El patio.{/b} Tras una puerta sellada se extiende el patio interior, donde los soldados muertos del castillo y los ferocanis de {link:archmage-arugal}Arugal{/link} montan guardia juntos.
• {b}Los salones de la casa.{/b} {link:razorclaw-the-butcher}Razorclaw el Carnicero{/link} trabaja en las cocinas. El fantasma del barón {link:baron-silverlaine}Silverlaine{/link} ronda el comedor, y el comandante {link:commander-springvale}Springvale{/link} mantiene una sala de consejo con sus oficiales muertos.
• {b}Las alturas.{/b} {link:odo-the-blindwatcher}Odo el Vigía Ciego{/link} tiene su atalaya en lo alto de las murallas. El maestro de lobos {link:wolf-master-nandos}Nandos{/link} lleva a su jauría por el patio superior, y {link:fenrus-the-devourer}Fenrus el Devorador{/link} guarda las cámaras de su amo.
• {b}El refugio de Arugal.{/b} En lo alto del castillo, el archimago espera entre sus sirvientes.]=],
		},
	},
})

Translate("esES", "archmage-arugal", {
	title = "Archimago Arugal",
	subtitle = "Señor del Castillo de Colmillo Oscuro",
	found = "Los salones más altos del Castillo de Colmillo Oscuro",
	hint = [=[Infórmese sobre él en El Sepulcro, o suba a lo alto del Castillo de Colmillo Oscuro.]=],
	allegiance = "Hijos de Arugal · antes el Kirin Tor",
	aliases = { "Arugal" },
	sections = {
		{
			title = "Resumen",
			text = [=[Arugal fue un archimago del {link:kirin-tor}Kirin Tor{/link} de {link:city-of-dalaran}Dalaran{/link}. En la {link:third-war}Tercera Guerra{/link}, cuando los magos de su orden morían y se alzaban de nuevo para la {link:scourge}Plaga{/link}, invocó a los {red:worgen}ferocanis{/red} para que lucharan por ellos. Los ferocanis masacraron a los muertos y después se volvieron contra los vivos. Enloquecido por la culpa, Arugal tomó a las bestias como sus hijos, se apoderó del castillo del barón {link:baron-silverlaine}Silverlaine{/link} y lo llamó {link:shadowfang-keep}Castillo de Colmillo Oscuro{/link}. Desde allí, su maldición se ha extendido por el {link:silverpine-forest}Bosque de Argénteos{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Arugal es la raíz de la plaga de ferocanis en {link:silverpine-forest}Argénteos{/link}. Sus grilletes atan a los aldeanos de {link:pyrewood-village}Piroleña{/link}, su magia corrompió a los mineros de la {link:deep-elem-mine}Mina de Elem{/link}, y sus hijos cazan en los caminos. Para los {link:forsaken}Renegados{/link}, es el último gran obstáculo para dominar el bosque.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Primero se alojó en una granja de trigo del norte de {link:silverpine-forest}Argénteos{/link}, y allí dejó sus libros de hechizos.
• Invocó a los ferocanis contra la voluntad de sus iguales.
• Maldijo la {link:pyrewood-village}Aldea Piroleña{/link}, y la gobierna a través de su consejo.
• Tomó el castillo del barón {link:baron-silverlaine}Silverlaine{/link} e hizo de sus muertos su servidumbre.
• Tiene una gran bestia, {link:fenrus-the-devourer}Fenrus{/link}, y sirvientes de la sombra de más allá del mundo.
• En combate maldice a sus enemigos con la forma de ferocanis, y hace caer sobre ellos descargas de vacío y truenos.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días recoge la vida de Arugal antes de la {link:third-war}Tercera Guerra{/link}, ni de dónde vinieron realmente sus ferocanis.]=],
		},
	},
	chapters = {
		{
			title = "El remedio",
			hint = [=[Recupere el hechizo del archimago en la granja donde se alojó una vez.]=],
			text = [=[Entre los libros que Arugal dejó en la granja había un hechizo que él llamaba su remedio. {link:dalar-dawnweaver}Dalar Dawnweaver{/link}, que había conocido al {link:kirin-tor}Kirin Tor{/link} desde dentro, lo leyó con desprecio. Se preguntó en voz alta cómo un hombre así había sido admitido alguna vez en la orden. Los hechizos de Arugal, dijo, eran tan endebles que cualquier aprendiz podía ver a través de ellos.]=],
		},
		{
			title = "Los grilletes de Piroleña",
			hint = [=[Lleve los grilletes de Piroleña al archimago muerto de El Sepulcro.]=],
			text = [=[Arugal compensaba la debilidad de su magia con objetos encantados. Cada ferocanis de los Moonrage llevaba su grillete, y también cada aldeano de {link:pyrewood-village}Piroleña{/link}, humanos de día y bestias de noche. De esos grilletes extrajo {link:dalar-dawnweaver}Dalar{/link} el poder que necesitaba para comprender la maldición.]=],
		},
		{
			title = "El farsante",
			hint = [=[Ayude al archimago muerto a probar lo que afirma con restos de La Muralla de Cringrís.]=],
			text = [=[Con el tiempo, {link:dalar-dawnweaver}Dalar{/link} llegó a un veredicto que nadie esperaba. Los grilletes probaban que Arugal podía atar a los ferocanis. No probaban que él los hubiera creado. Su famosa maldición era demasiado débil para durar. Los ferocanis, dijo Dalar, propagaban su maldición de algún otro modo.]=],
		},
		{
			title = "La muerte de Arugal",
			hint = [=[Suba a lo alto del Castillo de Colmillo Oscuro y ponga fin a los hechizos del archimago.]=],
			text = [=[{link:dalar-dawnweaver}Dalar{/link} no iba a permitir que {link:sylvanas-windrunner}la Dama Oscura{/link} reclamara {link:silverpine-forest}Argénteos{/link} mientras Arugal viviera, y pidió la cabeza del archimago. En lo alto de su castillo, entre sus sirvientes y sus hijos, Arugal fue abatido. Su cabeza fue llevada de vuelta a {link:the-sepulcher}El Sepulcro{/link}.]=],
		},
	},
	mentions = {
		{ text = "La locura de Arugal, el remedio" },
		{ text = "La locura de Arugal, los grilletes" },
		{ text = "La locura de Arugal, un nuevo veredicto" },
		{ text = "Detener la propagación" },
		{ text = "Emboscada en {link:pyrewood-village}Piroleña{/link}" },
		{ text = "Arugal debe morir" },
	},
	bonds = {
		{ id = "dalar-dawnweaver", name = "Dalar Dawnweaver", note = "lo desprecia" },
		{ id = "baron-silverlaine", name = "Barón Silverlaine", note = "ronda su castillo" },
		{ id = "fenrus-the-devourer", name = "Fenrus el Devorador", note = "su gran mascota" },
		{ id = "pyrewood-villagers", name = "Aldeanos de Piroleña", note = "malditos por él" },
		{ id = "apothecary-berard", name = "Boticario Berard", note = "perdió la razón por la maldición" },
	},
})

Translate("esES", "baron-silverlaine", {
	title = "Barón Silverlaine",
	subtitle = "El fantasma vengativo",
	found = "El comedor del Castillo de Colmillo Oscuro",
	hint = [=[Busque el fantasma del antiguo señor del castillo en su comedor.]=],
	allegiance = "Casa de Silverlaine",
	aliases = { "Silverlaine" },
	sections = {
		{
			title = "Resumen",
			text = [=[El barón Silverlaine era el noble señor del castillo que se alza sobre {link:pyrewood-village}Piroleña{/link}. Cuando llegaron los ferocanis de {link:archmage-arugal}Arugal{/link}, asediaron su hogar, y este cayó. Silverlaine murió con él. No descansó. Su fantasma recorre el comedor donde antaño celebraba banquetes, entre los sirvientes muertos de su casa, y descarga su ira sobre todo el que entra allí sin permiso.]=],
		},
		{
			title = "Importancia",
			text = [=[Silverlaine es la primera víctima de la locura de {link:archmage-arugal}Arugal{/link} dentro del castillo, y su señor legítimo. El castillo fue suyo antes de ser {link:shadowfang-keep}Colmillo Oscuro{/link}. Cayó rápidamente en la sombra y la ruina, y los ferocanis que lo tomaron merodean ahora por las estancias que rodean su salón. Su espíritu vengativo recuerda que el archimago levantó su refugio sobre las tumbas de otros.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Su castillo fue asediado por los ferocanis, y cayó.
• Su casa murió con él, y sus muertos aún sirven en los salones.
• En la muerte, lanza sobre sus enemigos un velo de sombra que debilita todo toque sanador.
• Aún lleva el sello de su familia.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días recoge el nombre de pila del barón, su familia ni el señor al que servía. No está escrito por qué su fantasma permanece cuando tantos otros se han marchado.]=],
		},
	},
	chapters = {
		{
			title = "El señor del comedor",
			hint = "Enfréntese al fantasma del barón en su propio salón.",
			text = [=[Los muertos de la casa siguen atados al castillo. Servidores y guardias gimen en sus salones, y el barón camina entre ellos en su comedor. No pudo mantener a los ferocanis fuera de su casa. No ha perdonado a nadie que haya entrado en ella desde entonces.]=],
		},
	},
	mentions = {
		{ text = "{link:archmage-arugal}Arugal{/link} debe morir" },
	},
	bonds = {
		{ id = "archmage-arugal", name = "Archimago Arugal", note = "tomó su castillo" },
		{ id = "commander-springvale", name = "Comandante Springvale", note = "manda a sus soldados muertos" },
	},
})

Translate("esES", "commander-springvale", {
	title = "Comandante Springvale",
	subtitle = "Comandante de la guardia muerta",
	found = "Una sala de consejo del Castillo de Colmillo Oscuro",
	hint = [=[Enfréntese al comandante muerto que aún mantiene su puesto en el castillo.]=],
	allegiance = "Casa de Silverlaine",
	aliases = { "Springvale" },
	sections = {
		{
			title = "Resumen",
			text = [=[El comandante Springvale dirigía a los soldados del barón {link:baron-silverlaine}Silverlaine{/link}. Cuando los ferocanis asaltaron el castillo, cayó en su puesto, y se alzó de nuevo como uno de sus muertos. Aún mantiene una sala de consejo con sus oficiales atormentados, y los fantasmas de sus guardias gimen por los salones que lo rodean.]=],
		},
		{
			title = "Importancia",
			text = [=[En vida, Springvale fue un siervo de la {link:holy-light}Luz Sagrada{/link}, y la Luz no lo ha abandonado del todo. Aún cura sus heridas con ella, se protege con ella y derriba a sus enemigos con el martillo de la justicia. Es una visión amarga: un defensor del castillo, convertido por la muerte en un guardián más de la guarida de {link:archmage-arugal}Arugal{/link}. No está solo en ese destino. Oficiales atormentados lo acompañan, guardias gimientes recorren los salones, y servidores embrujados aún atienden las estancias de un señor que ya no está.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Mandaba a los soldados del barón.
• Murió en la caída del castillo.
• Aún monta guardia, con sus oficiales, sobre estancias que ya no pertenecen a su señor.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica de estos días recoge el nombre de Springvale antes del castillo, ni dónde aprendió a empuñar la Luz.]=],
		},
	},
	chapters = {
		{
			title = "La última guardia",
			hint = "Enfréntese al comandante muerto y a sus oficiales.",
			text = [=[El castillo ha caído y su señor ha muerto. Aun así, Springvale mantiene su puesto, con sus oficiales a su lado. Cuando entran extraños, invoca la Luz contra ellos, como hizo contra los ferocanis.]=],
		},
	},
	mentions = {
		{ text = "{link:archmage-arugal}Arugal{/link} debe morir" },
	},
	bonds = {
		{ id = "baron-silverlaine", name = "Barón Silverlaine", note = "su señor" },
		{ id = "archmage-arugal", name = "Archimago Arugal", note = "señor del castillo por el que murió" },
	},
})

